// Package calc implements the calc subcommand: a 64-bit signed integer
// expression evaluator, one expression per input line.
package calc

import (
	"bufio"
	"errors"
	"io"
	"math"
	"strconv"
)

// Evaluation errors. Callers of Run only see "error" in the output; the
// distinct values exist for Eval's callers and for tests.
var (
	ErrSyntax    = errors.New("syntax error")
	ErrDivByZero = errors.New("division by zero")
	ErrOverflow  = errors.New("integer overflow")
)

// Run executes the calc subcommand, reading from r and writing to w.
//
// Each input line is evaluated independently. Its value, or "error", is
// written on its own line; blank lines (only spaces and tabs) produce no
// output.
func Run(r io.Reader, w io.Writer) error {
	br := bufio.NewReaderSize(r, 1<<16)
	var (
		ev   evaluator
		long []byte // accumulates lines longer than br's buffer
		out  []byte
	)
	for {
		chunk, err := br.ReadSlice('\n')
		if errors.Is(err, bufio.ErrBufferFull) {
			long = append(long, chunk...)
			continue
		}
		if err != nil && !errors.Is(err, io.EOF) {
			return err
		}
		line := chunk
		if len(long) > 0 {
			long = append(long, chunk...)
			line = long
		}
		if n := len(line); n > 0 && line[n-1] == '\n' {
			line = line[:n-1]
		}

		if !isBlank(line) {
			out = out[:0]
			if v, everr := ev.eval(line); everr == nil {
				out = strconv.AppendInt(out, v, 10)
				out = append(out, '\n')
			} else {
				out = append(out, "error\n"...)
			}
			if _, werr := w.Write(out); werr != nil {
				return werr
			}
		}

		if err != nil { // io.EOF
			return nil
		}
		long = long[:0]
	}
}

// Eval evaluates a single expression. It returns ErrSyntax for input that
// does not match the grammar (including blank input), ErrDivByZero for a
// division or remainder by zero, and ErrOverflow when a literal or an
// intermediate result does not fit in an int64.
func Eval(expr string) (int64, error) {
	var ev evaluator
	return ev.eval([]byte(expr))
}

// op is an entry on the operator stack.
type op byte

const (
	opParen op = '('
	opNeg   op = '~'
	opAdd   op = '+'
	opSub   op = '-'
	opMul   op = '*'
	opDiv   op = '/'
	opRem   op = '%'
)

// prec returns the binding strength of o; parentheses bind weakest so that
// they are never popped by an operator.
func (o op) prec() int {
	switch o {
	case opAdd, opSub:
		return 1
	case opMul, opDiv, opRem:
		return 2
	case opNeg:
		return 3
	default:
		return 0
	}
}

// evaluator is an operator-precedence (shunting-yard) evaluator. It uses
// explicit stacks rather than recursion so that deeply nested input cannot
// exhaust the goroutine stack. The stacks are reused across calls.
type evaluator struct {
	vals []int64
	ops  []op
}

func (e *evaluator) eval(s []byte) (int64, error) {
	e.vals = e.vals[:0]
	e.ops = e.ops[:0]

	expectOperand := true
	for i := 0; i < len(s); {
		c := s[i]
		if c == ' ' || c == '\t' {
			i++
			continue
		}

		if expectOperand {
			switch {
			case isDigit(c):
				v, n, err := parseNumber(s[i:])
				if err != nil {
					return 0, err
				}
				e.vals = append(e.vals, v)
				i += n
				expectOperand = false
				continue
			case c == '-':
				e.ops = append(e.ops, opNeg)
			case c == '(':
				e.ops = append(e.ops, opParen)
			default:
				return 0, ErrSyntax
			}
			i++
			continue
		}

		switch o := op(c); o {
		case opAdd, opSub, opMul, opDiv, opRem:
			// All binary operators are left-associative: reduce everything
			// on the stack that binds at least as tightly.
			if err := e.reduce(o.prec()); err != nil {
				return 0, err
			}
			e.ops = append(e.ops, o)
			expectOperand = true
		case ')':
			if err := e.reduce(1); err != nil {
				return 0, err
			}
			if len(e.ops) == 0 {
				return 0, ErrSyntax // unmatched ')'
			}
			e.ops = e.ops[:len(e.ops)-1] // pop '('
		default:
			return 0, ErrSyntax
		}
		i++
	}

	if expectOperand {
		return 0, ErrSyntax // missing operand
	}
	if err := e.reduce(1); err != nil {
		return 0, err
	}
	if len(e.ops) != 0 || len(e.vals) != 1 {
		return 0, ErrSyntax // unmatched '('
	}
	return e.vals[0], nil
}

// reduce applies operators from the top of the stack while they bind at
// least as tightly as minPrec. It stops at an opening parenthesis.
func (e *evaluator) reduce(minPrec int) error {
	for len(e.ops) > 0 {
		o := e.ops[len(e.ops)-1]
		if o.prec() < minPrec {
			return nil
		}
		e.ops = e.ops[:len(e.ops)-1]

		if o == opNeg {
			top := &e.vals[len(e.vals)-1]
			if *top == math.MinInt64 {
				return ErrOverflow
			}
			*top = -*top
			continue
		}

		n := len(e.vals)
		v, err := apply(o, e.vals[n-2], e.vals[n-1])
		if err != nil {
			return err
		}
		e.vals[n-2] = v
		e.vals = e.vals[:n-1]
	}
	return nil
}

// apply computes a o b, reporting overflow and division by zero.
func apply(o op, a, b int64) (int64, error) {
	switch o {
	case opAdd:
		c := a + b
		if (c > a) != (b > 0) {
			return 0, ErrOverflow
		}
		return c, nil
	case opSub:
		c := a - b
		if (c < a) != (b > 0) {
			return 0, ErrOverflow
		}
		return c, nil
	case opMul:
		if a == 0 || b == 0 {
			return 0, nil
		}
		c := a * b
		if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || c/b != a {
			return 0, ErrOverflow
		}
		return c, nil
	case opDiv:
		if b == 0 {
			return 0, ErrDivByZero
		}
		if a == math.MinInt64 && b == -1 {
			return 0, ErrOverflow
		}
		return a / b, nil
	case opRem:
		if b == 0 {
			return 0, ErrDivByZero
		}
		if b == -1 {
			return 0, nil // avoids the MinInt64 % -1 trap; the result is always 0
		}
		return a % b, nil
	}
	panic("calc: unknown operator " + strconv.Quote(string(o)))
}

// parseNumber parses the maximal run of decimal digits at the start of s,
// returning its value and length.
func parseNumber(s []byte) (int64, int, error) {
	var v int64
	n := 0
	for ; n < len(s) && isDigit(s[n]); n++ {
		d := int64(s[n] - '0')
		if v > (math.MaxInt64-d)/10 {
			return 0, n, ErrOverflow
		}
		v = v*10 + d
	}
	return v, n, nil
}

// isBlank reports whether s holds only spaces and tabs.
func isBlank(s []byte) bool {
	for _, c := range s {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

func isDigit(c byte) bool { return '0' <= c && c <= '9' }

// Package lru implements the lru subcommand: an LRU cache simulator driven
// by commands read from its input.
package lru

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
)

// maxCapacity is the largest capacity accepted on the first input line.
const maxCapacity = 1_000_000

// Run executes the lru subcommand, reading from r and writing to w.
//
// The first line holds the cache capacity; every later line is one of
// SET, GET, DEL or SIZE. Blank lines and unrecognised commands are ignored.
func Run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 64*1024), 1<<20)

	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return err
		}
		return errors.New("missing capacity line")
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}
	if capacity < 1 || capacity > maxCapacity {
		return fmt.Errorf("capacity %d out of range [1, %d]", capacity, maxCapacity)
	}

	c := newCache(capacity)
	bw, ok := w.(*bufio.Writer)
	if !ok {
		bw = bufio.NewWriter(w)
	}
	for sc.Scan() {
		if err := execute(c, bytes.TrimSuffix(sc.Bytes(), []byte{'\r'}), bw); err != nil {
			return err
		}
	}
	if err := sc.Err(); err != nil {
		return err
	}
	return bw.Flush()
}

// execute runs a single command line against c, writing any output to w.
func execute(c *cache, line []byte, w *bufio.Writer) error {
	cmd, rest, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if !ok || len(key) == 0 {
			return nil
		}
		c.set(key, value)
		return nil
	case "GET":
		value, ok := c.get(rest)
		if !ok {
			_, err := w.WriteString("NULL\n")
			return err
		}
		w.WriteString(value)
		return w.WriteByte('\n')
	case "DEL":
		if c.del(rest) {
			_, err := w.WriteString("1\n")
			return err
		}
		_, err := w.WriteString("0\n")
		return err
	case "SIZE":
		w.Write(strconv.AppendInt(w.AvailableBuffer(), int64(c.len()), 10))
		return w.WriteByte('\n')
	}
	return nil
}

// nilIndex marks the absence of a node in the intrusive list.
const nilIndex = -1

// node is an entry of the recency list. Nodes live in a slice and link to
// each other by index, which keeps them compact and free of GC pointers
// beyond the key and value strings.
type node struct {
	key, value string
	prev, next int32
}

// cache is a fixed-capacity LRU cache. Every operation runs in O(1)
// expected time: a map locates a key's node, and a doubly linked list
// ordered from most (head) to least (tail) recently used tracks recency.
type cache struct {
	capacity   int
	index      map[string]int32
	nodes      []node
	free       []int32 // slots of deleted nodes available for reuse
	head, tail int32
}

func newCache(capacity int) *cache {
	// Avoid committing memory for a huge capacity up front; the map and
	// node slice grow on demand.
	hint := min(capacity, 1<<16)
	return &cache{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		nodes:    make([]node, 0, hint),
		head:     nilIndex,
		tail:     nilIndex,
	}
}

func (c *cache) len() int { return len(c.index) }

// get returns the value stored under key and marks it most recently used.
func (c *cache) get(key []byte) (string, bool) {
	i, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// set stores value under key, marks it most recently used and evicts the
// least recently used key if the cache exceeds its capacity.
func (c *cache) set(key, value []byte) {
	if i, ok := c.index[string(key)]; ok {
		n := &c.nodes[i]
		if n.value != string(value) {
			n.value = string(value)
		}
		c.moveToFront(i)
		return
	}

	if len(c.index) >= c.capacity {
		// Evict the tail and reuse its slot for the new key.
		i := c.tail
		c.unlink(i)
		delete(c.index, c.nodes[i].key)
		c.insert(i, key, value)
		return
	}

	var i int32
	if n := len(c.free); n > 0 {
		i = c.free[n-1]
		c.free = c.free[:n-1]
	} else {
		i = int32(len(c.nodes))
		c.nodes = append(c.nodes, node{})
	}
	c.insert(i, key, value)
}

// del removes key and reports whether it was present.
func (c *cache) del(key []byte) bool {
	i, ok := c.index[string(key)]
	if !ok {
		return false
	}
	c.unlink(i)
	delete(c.index, c.nodes[i].key)
	c.nodes[i] = node{}
	c.free = append(c.free, i)
	return true
}

// insert fills slot i with a new entry and links it at the front.
func (c *cache) insert(i int32, key, value []byte) {
	k := string(key)
	c.nodes[i] = node{key: k, value: string(value)}
	c.index[k] = i
	c.pushFront(i)
}

func (c *cache) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *cache) pushFront(i int32) {
	n := &c.nodes[i]
	n.prev = nilIndex
	n.next = c.head
	if c.head != nilIndex {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *cache) unlink(i int32) {
	n := &c.nodes[i]
	if n.prev != nilIndex {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilIndex {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = nilIndex, nilIndex
}

// Package wordfreq implements the wordfreq subcommand: it prints the ten
// most frequent words of its input.
package wordfreq

import (
	"errors"
	"fmt"
	"io"
)

// topN is the maximum number of words reported.
const topN = 10

// entry is a distinct word and the number of times it occurred.
type entry struct {
	word  string
	count int
}

// less reports whether a ranks before b: higher count first, then
// ascending byte order of the word.
func (a entry) less(b entry) bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// counter accumulates word frequencies.
type counter struct {
	index   map[string]int // word -> position in entries
	entries []entry
}

func newCounter() *counter {
	return &counter{index: make(map[string]int)}
}

// add records one occurrence of word. word is not retained.
func (c *counter) add(word []byte) {
	// The map lookup with a string(word) conversion does not allocate;
	// a copy is made only when a new word is first seen.
	if i, ok := c.index[string(word)]; ok {
		c.entries[i].count++
		return
	}
	s := string(word)
	c.index[s] = len(c.entries)
	c.entries = append(c.entries, entry{word: s, count: 1})
}

// top returns up to n entries in rank order.
func (c *counter) top(n int) []entry {
	best := make([]entry, 0, n+1)
	for _, e := range c.entries {
		if len(best) == n && !e.less(best[n-1]) {
			continue
		}
		// Insert e at its sorted position, dropping the overflow.
		i := len(best)
		for i > 0 && e.less(best[i-1]) {
			i--
		}
		best = append(best, entry{})
		copy(best[i+1:], best[i:])
		best[i] = e
		if len(best) > n {
			best = best[:n]
		}
	}
	return best
}

// lower maps ASCII letters to their lowercase form and every other byte
// to 0, marking it as a separator.
var lower = func() (t [256]byte) {
	for b := 'a'; b <= 'z'; b++ {
		t[b] = byte(b)
		t[b-'a'+'A'] = byte(b)
	}
	return t
}()

// count reads all of r and returns the frequency of every word in it.
func count(r io.Reader) (*counter, error) {
	c := newCounter()
	buf := make([]byte, 1<<16)
	var word []byte // lowercase word in progress, possibly spanning reads
	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			if l := lower[b]; l != 0 {
				word = append(word, l)
			} else if len(word) > 0 {
				c.add(word)
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		c.add(word)
	}
	return c, nil
}

// Run executes the wordfreq subcommand, reading from r and writing to w.
func Run(r io.Reader, w io.Writer) error {
	c, err := count(r)
	if err != nil {
		return err
	}
	for _, e := range c.top(topN) {
		if _, err := fmt.Fprintf(w, "%d %s\n", e.count, e.word); err != nil {
			return err
		}
	}
	return nil
}

package wordfreq

import (
	"io"
	"strings"
	"testing"
)

func TestRun(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{"empty", "", ""},
		{"no words", "123 _ ' !?\n", ""},
		{"example", "The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"separators", "don't x_y a1b caf\xc3\xa9 \xff\xfeab", "1 a\n1 ab\n1 b\n1 caf\n1 don\n1 t\n1 x\n1 y\n"},
		{"top ten", "k j i h g f e d c b a a", "2 a\n1 b\n1 c\n1 d\n1 e\n1 f\n1 g\n1 h\n1 i\n1 j\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out strings.Builder
			if err := Run(strings.NewReader(tt.in), &out); err != nil {
				t.Fatal(err)
			}
			if got := out.String(); got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}

// oneByteReader returns at most one byte per Read, exercising words that
// span read boundaries.
type oneByteReader struct{ s string }

func (r *oneByteReader) Read(p []byte) (int, error) {
	if len(r.s) == 0 {
		return 0, io.EOF
	}
	n := copy(p[:1], r.s)
	r.s = r.s[n:]
	return n, nil
}

func TestRunSplitReads(t *testing.T) {
	var out strings.Builder
	if err := Run(&oneByteReader{"Hello hELLO world"}, &out); err != nil {
		t.Fatal(err)
	}
	if got, want := out.String(), "2 hello\n1 world\n"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

// Command app is a suite of independent subcommands. The first argument
// selects the subcommand, which reads standard input and writes standard
// output as described in SPEC.md.
package main

import (
	"bufio"
	"fmt"
	"io"
	"maps"
	"os"
	"slices"
	"strings"

	"suite/internal/calc"
	"suite/internal/lru"
	"suite/internal/wordfreq"
)

// runFunc is the entry point shared by every subcommand. Implementations
// read all input from r and write all output to w; they need not buffer
// or flush w themselves.
type runFunc func(r io.Reader, w io.Writer) error

var subcommands = map[string]runFunc{
	"calc":     calc.Run,
	"lru":      lru.Run,
	"wordfreq": wordfreq.Run,
}

func main() {
	if len(os.Args) < 2 {
		usage()
	}
	run, ok := subcommands[os.Args[1]]
	if !ok {
		fmt.Fprintf(os.Stderr, "app: unknown subcommand %q\n", os.Args[1])
		usage()
	}

	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	err := run(in, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "app %s: %v\n", os.Args[1], err)
		os.Exit(1)
	}
}

func usage() {
	names := slices.Sorted(maps.Keys(subcommands))
	fmt.Fprintf(os.Stderr, "usage: app <%s>\n", strings.Join(names, "|"))
	os.Exit(2)
}
